```c
static void
ssh_process_payload(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, ssh_channel_info_t *channel)
{
    tvbuff_t *next_tvb = tvb_new_subset_remaining(tvb, offset);
    if (channel->handle) {
        call_dissector(channel->handle, next_tvb, pinfo, proto_tree_get_root(tree));

        // If this is the "data-text-lines" dissector, add the text field
        if (channel->handle == data_text_lines_handle) {
            if (tvb_captured_length(next_tvb) > 0) {
                int off = 0;
                int next_off;
                int len;
                int tvb_len = tvb_captured_length(next_tvb);

                // Allocate buffer for text (twice the length to be safe)
                char *buf = malloc(tvb_len * 2);
                int out = 0;

                while (tvb_offset_exists(next_tvb, off)) {
                    len = tvb_find_line_end(next_tvb, off, -1, &next_off, FALSE);
                    if (len == -1)
                        break;

                    const uint8_t *line = tvb_get_ptr(next_tvb, off, len);
                    for (int i = 0; i < len; ++i) {
                        uint8_t c = line[i];
                            buf[out++] = (char)c;
                    }

                    // Append '\n' as separator if more lines remain
                    if (tvb_offset_exists(next_tvb, next_off)) {
                        buf[out++] = '\\';
                        buf[out++] = 'n';
                    }
                    off = next_off;
                }
                buf[out] = '\0';

                proto_tree_add_string(tree, hf_ssh_textonly, next_tvb, 0, tvb_len, buf);
            }
        }
    } else {
        call_data_dissector(next_tvb, pinfo, proto_tree_get_root(tree));
    }
}
```

